package resource_application_secret

import (
	"context"
	"strings"

	"github.com/Lenstra/terraform-provider-logto/client"
	"github.com/hashicorp/terraform-plugin-framework/path"
	"github.com/hashicorp/terraform-plugin-framework/resource"
	"github.com/hashicorp/terraform-plugin-framework/resource/schema"
	"github.com/hashicorp/terraform-plugin-framework/resource/schema/planmodifier"
	"github.com/hashicorp/terraform-plugin-framework/resource/schema/stringplanmodifier"
	"github.com/hashicorp/terraform-plugin-framework/types"
)

type secretResource struct{ client *client.Client }
type model struct {
	ID            types.String `tfsdk:"id"`
	ApplicationID types.String `tfsdk:"application_id"`
	Name          types.String `tfsdk:"name"`
	Value         types.String `tfsdk:"value"`
}

var _ resource.ResourceWithImportState = (*secretResource)(nil)
var _ resource.ResourceWithConfigure = (*secretResource)(nil)

func New() resource.Resource { return &secretResource{} }
func (r *secretResource) Metadata(_ context.Context, req resource.MetadataRequest, resp *resource.MetadataResponse) {
	resp.TypeName = req.ProviderTypeName + "_application_secret"
}
func (r *secretResource) Schema(_ context.Context, _ resource.SchemaRequest, resp *resource.SchemaResponse) {
	resp.Schema = schema.Schema{Description: "A named application secret generated by Logto. Import uses application-id/secret-name. Replacement explicitly rotates the owned secret.", Attributes: map[string]schema.Attribute{
		"id":             schema.StringAttribute{Computed: true, PlanModifiers: []planmodifier.String{stringplanmodifier.UseStateForUnknown()}},
		"application_id": schema.StringAttribute{Required: true, PlanModifiers: []planmodifier.String{stringplanmodifier.RequiresReplace()}},
		"name":           schema.StringAttribute{Required: true, PlanModifiers: []planmodifier.String{stringplanmodifier.RequiresReplace()}},
		"value":          schema.StringAttribute{Computed: true, Sensitive: true},
	}}
}
func (r *secretResource) Configure(_ context.Context, req resource.ConfigureRequest, resp *resource.ConfigureResponse) {
	if req.ProviderData == nil {
		return
	}
	var ok bool
	r.client, ok = req.ProviderData.(*client.Client)
	if !ok {
		resp.Diagnostics.AddError("Invalid provider client", "Expected a Logto API client.")
	}
}
func (r *secretResource) Create(ctx context.Context, req resource.CreateRequest, resp *resource.CreateResponse) {
	var m model
	resp.Diagnostics.Append(req.Plan.Get(ctx, &m)...)
	if resp.Diagnostics.HasError() {
		return
	}
	if m.ApplicationID.ValueString() == "" || m.Name.ValueString() == "" || strings.Contains(m.ApplicationID.ValueString(), "/") || strings.Contains(m.Name.ValueString(), "/") || m.Name.ValueString() == "." || m.Name.ValueString() == ".." {
		resp.Diagnostics.AddError("Invalid secret identifier", "Application ID and name must be nonempty and cannot contain '/'.")
		return
	}
	s, err := r.client.ApplicationSecretCreate(ctx, m.ApplicationID.ValueString(), m.Name.ValueString())
	if err != nil {
		resp.Diagnostics.AddError("Error creating application secret", err.Error())
		return
	}
	m.ID = types.StringValue(m.ApplicationID.ValueString() + "/" + m.Name.ValueString())
	m.Value = types.StringValue(s.Value)
	resp.Diagnostics.Append(resp.State.Set(ctx, &m)...)
}
func (r *secretResource) Read(ctx context.Context, req resource.ReadRequest, resp *resource.ReadResponse) {
	var m model
	resp.Diagnostics.Append(req.State.Get(ctx, &m)...)
	if resp.Diagnostics.HasError() {
		return
	}
	if m.ID.IsNull() || m.ID.IsUnknown() || m.ID.ValueString() == "" {
		resp.State.RemoveResource(ctx)
		return
	}
	// Composite ID also supports imported state with only id populated.
	app, name, ok := strings.Cut(m.ID.ValueString(), "/")
	if !ok || app == "" || name == "" {
		resp.Diagnostics.AddError("Invalid import ID", "Expected application-id/secret-name.")
		return
	}
	application, err := r.client.ApplicationGet(ctx, app)
	if err != nil {
		resp.Diagnostics.AddError("Error reading application", err.Error())
		return
	}
	if application == nil {
		resp.State.RemoveResource(ctx)
		return
	}
	secrets, err := r.client.GetApplicationSecrets(ctx, app)
	if err != nil {
		resp.Diagnostics.AddError("Error reading application secrets", err.Error())
		return
	}
	for _, s := range secrets {
		if s.Name == name {
			m.ApplicationID = types.StringValue(app)
			m.Name = types.StringValue(name)
			m.Value = types.StringValue(s.Value)
			resp.Diagnostics.Append(resp.State.Set(ctx, &m)...)
			return
		}
	}
	resp.State.RemoveResource(ctx)
}
func (r *secretResource) Update(_ context.Context, _ resource.UpdateRequest, resp *resource.UpdateResponse) {
	resp.Diagnostics.AddError("Unexpected update", "Application ID and name require replacement; value is read-only.")
}
func (r *secretResource) Delete(ctx context.Context, req resource.DeleteRequest, resp *resource.DeleteResponse) {
	var m model
	resp.Diagnostics.Append(req.State.Get(ctx, &m)...)
	if resp.Diagnostics.HasError() {
		return
	}
	app, name, ok := strings.Cut(m.ID.ValueString(), "/")
	if !ok || app == "" || name == "" {
		resp.Diagnostics.AddError("Invalid secret ID", "Expected application-id/secret-name.")
		return
	}
	if err := r.client.ApplicationSecretDelete(ctx, app, name); err != nil {
		resp.Diagnostics.AddError("Error deleting application secret", err.Error())
	}
}
func (r *secretResource) ImportState(ctx context.Context, req resource.ImportStateRequest, resp *resource.ImportStateResponse) {
	app, name, ok := strings.Cut(req.ID, "/")
	if !ok || app == "" || name == "" || strings.Contains(name, "/") || name == "." || name == ".." {
		resp.Diagnostics.AddError("Invalid import ID", "Expected application-id/secret-name.")
		return
	}
	resp.Diagnostics.Append(resp.State.SetAttribute(ctx, path.Root("id"), req.ID)...)
	resp.Diagnostics.Append(resp.State.SetAttribute(ctx, path.Root("application_id"), app)...)
	resp.Diagnostics.Append(resp.State.SetAttribute(ctx, path.Root("name"), name)...)
}
